    public static function count() { return count(self::entries()); }

    private static function norm($s) { return class_exists('Mutqan_Playbook') ? Mutqan_Playbook::norm($s) : mb_strtolower(trim((string) $s)); }

    /** The entries this message is about, best first: [[id, kind, guidance, answer, score], …]. */
    public static function match($text, $max = 4) {
        $n = ' ' . self::norm($text) . ' ';
        if (trim($n) === '') { return []; }
        $hits = [];
        foreach (self::entries() as $id => $e) {
            $score = 0;
            foreach ($e[1] as $w) {
                $w = self::norm($w);
                if ($w === '' || mb_strpos($n, $w) === false) { continue; }
                $score += 2 + min(4, (int) floor(mb_strlen($w) / 4));   // longer phrases are surer
            }
            if ($score > 0) { $hits[] = [$id, $e[0], $e[2], $e[3], $score]; }
        }
        usort($hits, function ($a, $b) { return $b[4] <=> $a[4] ?: strcmp($a[0], $b[0]); });
        return array_slice($hits, 0, $max);
    }

    /** Internal guidance for the model on this customer message ('' when nothing fits). */
    public static function context($text) {
        $m = self::match($text, 4);
        if (!$m) { return ''; }
        $L = ['## من موسوعة خدمة العملاء (إرشاد داخلي — استخدمه في ردك بكلامك، لا تنسخه كقائمة)'];
        foreach ($m as $x) { $L[] = '- ' . $x[2]; }
        return implode("\n", $L) . "\n";
    }

    /** A ready answer when no model is reachable: only a clear, single best match with a written answer. */
    public static function answer($text) {
        $m = self::match($text, 2);
        if (!$m || $m[0][3] === '') { return ''; }
        if (isset($m[1]) && $m[1][4] >= $m[0][4] && $m[1][3] === '') { return ''; }
        return $m[0][3];
    }

    /** For Mutqan_AI::run — customer conversations only, matched on the customer's own last message. */
    public static function inject($prompt, $opts, $p) {
        $feature = (string) ($opts['feature'] ?? '');
        if (!in_array($feature, ['chat', 'site_chat', 'wa', 'wa_hub', 'wa_reception', 'negotiate', 'sales', 'order_chat'], true)) { return $prompt; }
        $last = '';
        foreach (preg_split('/\r?\n/u', (string) $prompt) as $l) { if (preg_match('/^\s*العميل(?:\s*\([^)]*\))?\s*:\s*(.+)$/u', $l, $mm)) { $last = trim($mm[1]); } }
        if ($last === '') { return $prompt; }
        $ctx = self::context($last);
        return $ctx === '' ? $prompt : $ctx . "\n" . $prompt;
    }
}
